<script lang="ts">
    import Page from '../../components/Page.svelte';
    import Field from '../../components/Field.svelte';
    import Notice from '../../components/Notice.svelte';
    import Strength from '../../components/Strength.svelte';
    import Setting from '../../components/Setting.svelte';
    import AdminPage from '../../components/AdminPage.svelte';
    import type { PageBoot } from '../types';
    import { pageUrl, type UserBootstrap } from '../../lib/bootstrap';
    import { useI18n } from '../../lib/i18n';
    type Data = Record<string, any>;
    type PermissionDefinition = { id: string; label: string; description?: string|null; scopeKinds: string[] };
    type ActionGroup = { id: string; label: string; description?: string|null; permissionIds: string[] };
    let { boot }: { boot: PageBoot } = $props();
    const p = $derived(boot.props);
    const user = $derived((p.user ?? p.currentUser ?? null) as UserBootstrap | null);
    const csrf = $derived(p.csrfToken ?? '');
    const t = useI18n();
    const url = (name: string, parameters: Record<string, string | number> = {}) => pageUrl(boot.urls, name, parameters);
    const list = <T=Data>(v: T[]|null|undefined): T[] => v ?? [];
    const enc = (v: unknown) => encodeURIComponent(String(v ?? ''));
    const ask = (e: Event, text: string) => { if (!confirm(text)) e.preventDefault(); };
    let score = $state<number|null>(null);
    const strength = (e: Event) => { const value = (e.currentTarget as HTMLInputElement).value; void import('zxcvbn').then(({default: zxcvbn}) => score = zxcvbn(value).score); };
    const permissionDefinitions = $derived(list<PermissionDefinition>(p.permissionDefinitions));
    const actionGroups = $derived(list<ActionGroup>(p.actionGroups));
    const groupedPermissionIds = $derived(new Set(actionGroups.flatMap(group => group.permissionIds)));
    const ungroupedPermissions = $derived(permissionDefinitions.filter(definition => !groupedPermissionIds.has(definition.id)));
    const permissionLabel = (id: string) => t(permissionDefinitions.find(definition => definition.id === id)?.label ?? id);
    const actionGroupLabel = (group: ActionGroup) => t(group.label);
    const sensitivePermission = (id: string) => ['user.manage','role.manage','system.settings.manage','system.schema.manage','system.accounts.access','system.impersonation.execute'].includes(id);
</script>

{#if boot.page==='admin'}<Page title={t('navigation.admin')}><div class="settings-list">{#each list<{key:string;href:string}>(p.areas) as area}<Setting title={t(area.key)} text="" href={area.href}/>{:else}<p class="empty">{t('http.error.forbidden')}</p>{/each}</div></Page>
{:else if boot.page==='accounts/edit'}<Page title={p.account?.name??t('page.accounts.title')} error={p.error} success={p.success} narrow><div class="page-actions"><a class="button" href={url("accounts")}>← {t('navigation.accounts')}</a>{#if p.canReadAudit}<a class="button" href={`/accounts/${enc(p.account.id)}/audit`}>{t('audit.title')}</a>{/if}{#if p.canManageMembers}<a class="button" href={url("accountMembers", { id: p.account.id })}>{t('accounts.members')}</a>{/if}{#if p.canViewProviders}<a class="button" href={url('accountProviders', { id: p.account.id })}>{t('navigation.providers')}</a>{/if}{#if p.canListZones}<a class="button" href={url('accountZones', { account: p.account.id })}>{t('navigation.zones')}</a>{/if}</div>{#if p.account}<section class="box"><h2 class="subtitle">{p.account.type==='personal'?t('profile.account.personal'):t('account.organization-details')}</h2><p><code>{p.account.slug}</code></p><p class="status">{p.account.isActive?t('account.status.active'):t('account.status.inactive')}</p>{#if p.account.type==='personal'}<p>{t('account.personal-managed-profile')}</p>{:else if p.canEditAccount}<form method="post"><input type="hidden" name="csrf_token" value={csrf}><Field label={t('field.name')}><input class="input" name="name" value={p.account.name} maxlength="255" required></Field><Field label={t('account.customer-number')}><input class="input" name="customer_number" value={p.account.customerNumber??''} maxlength="64"></Field><Field label={t('account.external-reference')}><input class="input" name="external_reference" value={p.account.externalReference??''} maxlength="255"></Field><button class="button is-primary">{t('common.save')}</button></form>{/if}</section>{#if p.usage?.usedProviderAccounts===0 && p.canManageProviders}<p class="box">{t('account.workflow-provider-needed')} <a href={url('accountProviders', { id:p.account.id })}>{t('navigation.providers')}</a></p>{:else if p.usage?.usedZones===0 && p.canCreateZones}<p class="box">{t('account.workflow-zone-needed')} <a href={url('accountZones', { account:p.account.id })}>{t('navigation.zones')}</a></p>{/if}{#if p.usage}<section class="box"><h2 class="subtitle">{t('account.resources.title')}</h2><p>{t('account.resources.zones')}: {p.usage.usedZones} / {p.usage.maxZones===null?t('account.resources.unlimited'):p.usage.maxZones}</p><p>{t('account.resources.members')}: {p.usage.usedMembers} / {p.usage.maxMembers===null?t('account.resources.unlimited'):p.usage.maxMembers}</p><p>{t('account.resources.providers')}: {p.usage.usedProviderAccounts} / {p.usage.maxProviderAccounts===null?t('account.resources.unlimited'):p.usage.maxProviderAccounts}</p>{#if p.canEditAccount}<form class="form-grid mt-4" method="post"><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="action" value="limits"><Field label={t('account.resources.max-zones')}><input class="input" type="number" min="0" name="max_zones" value={p.usage.maxZones??''}></Field><Field label={t('account.resources.max-members')}><input class="input" type="number" min="0" name="max_members" value={p.usage.maxMembers??''}></Field><Field label={t('account.resources.max-providers')}><input class="input" type="number" min="0" name="max_provider_accounts" value={p.usage.maxProviderAccounts??''}></Field><button class="button">{t('account.resources.save-limits')}</button></form>{/if}</section>{/if}{#if p.canDeleteAccount || p.canReactivateAccount}<section class="box"><form class="buttons" method="post"><input type="hidden" name="csrf_token" value={csrf}>{#if p.canDeleteAccount}<button class="button" name="action" value="deactivate" onclick={(e)=>ask(e,t('account.confirm-deactivate'))}>{t('account.deactivate')}</button>{:else if p.canReactivateAccount}<button class="button is-primary" name="action" value="activate" onclick={(e)=>ask(e,t('account.confirm-activate'))}>{t('account.activate')}</button>{/if}{#if p.canDeleteAccount}<button class="button is-danger" name="action" value="delete" onclick={(e)=>ask(e,t('account.confirm-delete'))}>{t('account.delete')}</button>{/if}</form></section>{/if}{/if}</Page>
{:else if boot.page==='accounts/members'}<Page title={t('accounts.members')} error={p.error} success={p.success}><div class="page-actions"><a class="button" href={url("account", { id: p.account?.id ?? 0 })}>← {p.account?.name??t('navigation.accounts')}</a></div>{#if p.account}<section class="box"><h2 class="subtitle">{p.account.name}</h2><form class="form-grid" method="post"><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="action" value="invite"><Field label={t('field.email')}><input class="input" type="email" name="email" placeholder={t('accounts.invitation-email-placeholder')} required></Field><Field label={t('field.role')}><select class="input" name="role">{#each list(p.roles).filter(role=>role.value!=='owner') as role}<option value={role.value}>{t(`profile.role.${role.value}`)}</option>{/each}</select></Field><button class="button is-primary">{t('accounts.member-add')}</button></form>{#if p.canTransferOwnership}<form class="form-grid mt-4" method="post" action={`/accounts/${enc(p.account.id)}/ownership`} onsubmit={(e)=>ask(e,t('account.confirm-ownership-transfer'))}><input type="hidden" name="csrf_token" value={csrf}><Field label={t('account.new-owner')}><input class="input" name="user_id" placeholder={t('accounts.user-id-placeholder')} required></Field><button class="button">{t('account.transfer-ownership')}</button></form>{/if}</section>{#if list(p.invitations).length}<section class="box"><h2 class="subtitle">{t('accounts.invitations')}</h2>{#each list(p.invitations) as invitation}<article class="resource-card"><div><strong>{invitation.email}</strong><span class="status">{t(`account.invitation.status.${invitation.status}`)} · {t(`profile.role.${invitation.role}`)}</span><small>{invitation.expiresAt}</small></div>{#if invitation.status==='pending'}<form method="post"><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="action" value="revoke_invitation"><input type="hidden" name="invitation_id" value={invitation.id}><button class="button is-small is-danger">{t('accounts.invitation-revoke')}</button></form>{/if}</article>{/each}</section>{/if}<div class="resource-grid">{#each list(p.members) as member}<article class="resource-card"><div><strong>{member.displayName??member.email}</strong><small>{member.email}</small></div><div class="buttons">{#if member.role==='owner'}<span class="status">{t('profile.role.owner')}</span>{:else}<form method="post"><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="action" value="role"><input type="hidden" name="user_id" value={member.userId}><select class="input" name="role" onchange={(e)=>{const f=(e.currentTarget as HTMLSelectElement).form;if(f)f.submit()}}>{#each list(p.roles).filter(role=>role.value!=='owner') as role}<option value={role.value} selected={member.role===role.value}>{t(`profile.role.${role.value}`)}</option>{/each}</select></form><form method="post" onsubmit={(e)=>ask(e,t('account.confirm-member-remove'))}><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="action" value="remove"><input type="hidden" name="user_id" value={member.userId}><button class="button is-small is-danger">{t('common.remove')}</button></form>{/if}</div></article>{/each}</div>{/if}</Page>
{:else if boot.page==='accounts/list'}<Page title={t('page.accounts.title')} error={p.error}>{#if p.activeAccount}<p class="box"><strong>{t('dns.active-account')}: {p.activeAccount.name}</strong>{#if p.canListActiveZones} · <a href={url('accountZones', { account: p.activeAccount.id })}>{t('navigation.zones')}</a>{/if}</p>{/if}<section class="box"><form class="form-grid" method="post"><input type="hidden" name="csrf_token" value={csrf}><Field label={t('field.name')}><input class="input" name="name" required></Field><Field label={t('field.slug')}><input class="input" name="slug" pattern={'[a-z0-9-]{2,64}'} required></Field><button class="button is-primary">{t('accounts.create')}</button></form></section><section class="box"><form class="form-grid" method="get" action={url("accounts")}><Field label={t('accounts.search')}><input class="input" name="q" value={p.search??''}></Field><Field label={t('accounts.type-filter')}><select class="input" name="type"><option value="all" selected={p.type==='all'}>{t('common.all')}</option><option value="personal" selected={p.type==='personal'}>{t('profile.account.personal')}</option><option value="organization" selected={p.type==='organization'}>{t('profile.account.organization')}</option></select></Field><Field label={t('accounts.status-filter')}><select class="input" name="status"><option value="all" selected={p.status==='all'}>{t('common.all')}</option><option value="active" selected={p.status==='active'}>{t('account.status.active')}</option><option value="inactive" selected={p.status==='inactive'}>{t('account.status.inactive')}</option></select></Field><Field label={t('accounts.role-filter')}><select class="input" name="role"><option value="all" selected={p.role==='all'}>{t('common.all')}</option>{#each list(p.roles) as role}<option value={role.value} selected={p.role===role.value}>{t(`profile.role.${role.value}`)}</option>{/each}</select></Field><button class="button">{t('common.search')}</button></form></section><div class="resource-grid">{#each list(p.accounts) as account}<article class="resource-card" aria-current={p.activeAccountId===account.id ? 'true' : undefined}><div>{#if account.canViewAccount}<a class="resource-title" href={url("account", { id: account.id })}>{account.name}</a>{:else}<strong class="resource-title">{account.name}</strong>{/if}<small>{account.slug}</small>{#if p.activeAccountId===account.id}<span class="status">{t('account.selected')}</span>{/if}<span class="status">{t(`profile.account.${account.kind}`)} · {account.isActive?t('account.status.active'):t('account.status.inactive')}</span></div><div class="buttons">{#if account.isActive}<form method="post" action="/accounts/active"><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="account_id" value={account.id}><button class="button is-small" disabled={p.activeAccountId===account.id}>{p.activeAccountId===account.id?t('account.selected'):t('account.select')}</button></form>{/if}{#if account.canListZones}<a class="button is-small is-primary" href={url("accountZones", { account: account.id })}>{t('navigation.zones')}</a>{/if}{#if account.canViewAccount}<a class="button is-small" href={url("account", { id: account.id })}>{t(account.canEditAccount ? 'common.edit' : 'common.details')}</a>{/if}{#if account.canManageMembers}<a class="button is-small" href={url("accountMembers", { id: account.id })}>{t('accounts.members')}</a>{/if}{#if account.canViewProviders}<a class="button is-small" href={url("accountProviders", { id: account.id })}>{t('navigation.providers')}</a>{/if}</div></article>{:else}<p class="empty">{t('accounts.empty')} {t('account.workflow-empty')}</p>{/each}</div><div class="page-actions">{#if p.page>1}<a class="button" href={`${url("accounts")}?q=${enc(p.search)}&type=${enc(p.type)}&role=${enc(p.role)}&status=${enc(p.status)}&page=${p.page-1}`}>{t('accounts.previous-page')}</a>{/if}{#if p.hasNext}<a class="button" href={`${url("accounts")}?q=${enc(p.search)}&type=${enc(p.type)}&role=${enc(p.role)}&status=${enc(p.status)}&page=${p.page+1}`}>{t('accounts.next-page')}</a>{/if}</div></Page>
{:else if boot.page==='iam/user_edit'}
 <Page title={p.target?.displayName??p.target?.email??t('page.users.title')} error={p.error} success={p.success} narrow>
  {#if p.target}
   <div class="page-actions"><a class="button" href={url("users")}>← {t('navigation.users')}</a></div>
   <section class="box">
    <dl><dt>{t('field.email')}</dt><dd>{p.target.email}</dd><dt>{t('profile.user-id')}</dt><dd><code>{p.target.id}</code></dd></dl>
    <form method="post"><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="action" value="display_name"><Field label={t('field.display-name')}><input class="input" name="display_name" value={p.target.displayName??''} maxlength="64"></Field><button class="button is-primary">{t('common.save')}</button></form>
    <form method="post" class="mt-4"><input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="action" value="status"><input type="hidden" name="active" value={p.target.active?'0':'1'}><button class="button" class:is-danger={p.target.active}>{p.target.active?t('users.status.inactive'):t('users.status.active')}</button></form>
    <form method="post" action={`/users/${enc(p.target.id)}/delete`} class="mt-4" onsubmit={(e)=>ask(e,t('users.confirm-delete'))}><input type="hidden" name="csrf_token" value={csrf}><button class="button is-danger">{t('common.delete')}</button></form>
   </section>
   <section class="box">
    <h2 class="subtitle">{t('recovery.admin-title')}</h2>
    <p>{t('recovery.admin-help')}</p>
    {#if p.target.active}
     <form method="post" action={`/users/${enc(p.target.id)}/account-recovery`} onsubmit={(e)=>ask(e,t('recovery.admin-confirm',{email:p.target.email}))}>
      <input type="hidden" name="csrf_token" value={csrf}>
      <button class="button is-danger">{t('recovery.admin-authorize')}</button>
     </form>
    {:else}<Notice kind="warning" text={t('users.auth-recovery.active-required')}/>{/if}
   </section>
   {#if p.lastWebAuthnCredential}
    <section class="box">
     <h2 class="subtitle">{t('users.auth-recovery.title')}</h2>
