     <p class="muted">{p.lastWebAuthnCredential.name} · {p.lastWebAuthnCredential.created_at}</p>
     {#if !p.target.active}
      <Notice kind="warning" text={t('users.auth-recovery.active-required')}/>
     {:else if !p.passwordLoginEnabled}
      <Notice kind="warning" text={t('users.auth-recovery.password-required')}/>
     {:else}
      <form method="post" onsubmit={(e)=>ask(e,t('users.auth-recovery.confirm',{email:p.target.email}))}>
       <input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="action" value="revoke_last_webauthn"><input type="hidden" name="credential_id" value={p.lastWebAuthnCredential.credential_id}>
       <button class="button is-danger">{t('users.auth-recovery.revoke')}</button>
      </form>
     {/if}
     <details class="mt-4">
      <summary>{t('users.auth-recovery.password-reset-title')}</summary>
      <p>{t('users.auth-recovery.password-reset-help')}</p>
      <form method="post" class="form-grid mt-4">
       <input type="hidden" name="csrf_token" value={csrf}><input type="hidden" name="action" value="reset_password">
       <Field label={t('users.auth-recovery.new-password')}><input class="input" type="password" name="new_password" autocomplete="new-password" required></Field>
       <label class="checkbox"><input type="checkbox" name="keep_api_keys" value="1" checked> {t('users.auth-recovery.keep-api-keys')}</label>
       <button class="button">{t('users.auth-recovery.password-reset')}</button>
      </form>
     </details>
    </section>
   {/if}
   <section class="box"><h2 class="subtitle">{t('users.roles')}</h2><form method="post"><input type="hidden" name="csrf_token" value={csrf}><div class="form-grid">{#each list<Data>(p.allRoles) as role}<label class="checkbox"><input type="checkbox" name="roles[]" value={role.id} checked={list<Data>(p.target.roles).some(r=>r.id===role.id)}> {role.name}</label>{/each}</div><button class="button is-primary">{t('common.save')}</button></form></section>
  {/if}
 </Page>
{:else if boot.page==='iam/users'}<Page title={t('page.users.title')} error={p.error} success={p.success}><section class="box"><form class="form-grid" method="get" action={url("users")}><Field label={t('users.search')}><input class="input" name="q" value={p.search??''}></Field><Field label={t('users.status-filter')}><select class="input" name="status"><option value="active" selected={p.status==='active'}>{t('users.status.active')}</option><option value="inactive" selected={p.status==='inactive'}>{t('users.status.inactive')}</option><option value="all" selected={p.status==='all'}>{t('common.all')}</option></select></Field><Field label={t('users.account-filter')}><input class="input" name="account" value={p.account??''}></Field><Field label={t('users.membership-role-filter')}><select class="input" name="membership_role"><option value="all" selected={p.membershipRole==='all'}>{t('common.all')}</option>{#each list(p.membershipRoles) as role}<option value={role.value} selected={p.membershipRole===role.value}>{t(`profile.role.${role.value}`)}</option>{/each}</select></Field><button class="button">{t('common.search')}</button></form></section><section class="box"><form class="form-grid" method="post" action={url("users")}><input type="hidden" name="csrf_token" value={csrf}><Field label={t('field.email')}><input class="input" type="email" name="email" required></Field><Field label={t('field.password')}><input class="input" type="password" name="password" oninput={strength} required><Strength value={score}/></Field><button class="button is-primary">{t('users.create')}</button></form></section><div class="resource-grid">{#each list(p.users) as target}<article class="resource-card"><div><a class="resource-title" href={url("user", { id: target.id })}>{target.displayName??target.email}</a><span class="status">{target.active?t('users.status.active'):t('users.status.inactive')}</span><small>{target.email}</small>{#if list(target.roles).length}<small>{t('users.roles')}: {list<Data>(target.roles).map(role=>role.name).join(', ')}</small>{/if}</div></article>{:else}<p class="empty">{t('users.empty')}</p>{/each}</div><div class="page-actions">{#if p.page>1}<a class="button" href={`${url("users")}?q=${enc(p.search)}&status=${enc(p.status)}&account=${enc(p.account)}&membership_role=${enc(p.membershipRole)}&page=${p.page-1}`}>{t('users.previous-page')}</a>{/if}{#if p.hasNext}<a class="button" href={`${url("users")}?q=${enc(p.search)}&status=${enc(p.status)}&account=${enc(p.account)}&membership_role=${enc(p.membershipRole)}&page=${p.page+1}`}>{t('users.next-page')}</a>{/if}</div></Page>
{:else if boot.page==='iam/roles'}<Page title={t('page.roles.title')} error={p.error} success={p.success}><section class="box"><form method="post" action={url("roles")}><input type="hidden" name="csrf_token" value={csrf}><Field label={t('field.name')}><input class="input" name="name" required></Field>{#each actionGroups as group}<fieldset class="permission-group"><legend>{actionGroupLabel(group)}</legend>{#if group.description}<p class="muted">{t(group.description)}</p>{/if}<div class="form-grid">{#each group.permissionIds as permissionId}<label class="checkbox"><input type="checkbox" name="permissions[]" value={permissionId}> {permissionLabel(permissionId)}{#if sensitivePermission(permissionId)} <span class="status">{t('roles.sensitive-permission')}</span>{/if}</label>{/each}</div></fieldset>{/each}{#if ungroupedPermissions.length}<fieldset class="permission-group"><legend>{t('roles.individual-permissions')}</legend><div class="form-grid">{#each ungroupedPermissions as permission}<label class="checkbox"><input type="checkbox" name="permissions[]" value={permission.id}> {t(permission.label)}{#if sensitivePermission(permission.id)} <span class="status">{t('roles.sensitive-permission')}</span>{/if}</label>{/each}</div></fieldset>{/if}<button class="button is-primary mt-4">{t('roles.create')}</button></form></section><section class="box"><h2 class="subtitle">{t('roles.existing')}</h2><div class="resource-grid">{#each list(p.roles) as role}<article class="resource-card"><div><a class="resource-title" href={url("role", { id: role.id })}>{role.name}</a><span class="status">{role.isBuiltIn?t('roles.built-in'):t('roles.custom')}</span></div></article>{:else}<p class="empty">{t('roles.empty')}</p>{/each}</div></section></Page>
{:else if boot.page==='iam/role_edit'}<Page title={p.role?.name??t('page.role-edit.title')} error={p.error} success={p.success} narrow><div class="page-actions"><a class="button" href={url("roles")}>← {t('page.roles.title')}</a></div>{#if p.role}<section class="box"><form method="post"><input type="hidden" name="csrf_token" value={csrf}><Field label={t('field.name')}><input class="input" name="name" value={p.role.name} readonly={p.role.isBuiltIn} required></Field>{#each actionGroups as group}<fieldset class="permission-group" disabled={p.role.isBuiltIn}><legend>{actionGroupLabel(group)}</legend>{#if group.description}<p class="muted">{t(group.description)}</p>{/if}<div class="form-grid">{#each group.permissionIds as permissionId}<label class="checkbox"><input type="checkbox" name="permissions[]" value={permissionId} checked={list<string>(p.role.permissions).includes(permissionId)}> {permissionLabel(permissionId)}{#if sensitivePermission(permissionId)} <span class="status">{t('roles.sensitive-permission')}</span>{/if}</label>{/each}</div></fieldset>{/each}{#if ungroupedPermissions.length}<fieldset class="permission-group" disabled={p.role.isBuiltIn}><legend>{t('roles.individual-permissions')}</legend><div class="form-grid">{#each ungroupedPermissions as permission}<label class="checkbox"><input type="checkbox" name="permissions[]" value={permission.id} checked={list<string>(p.role.permissions).includes(permission.id)}> {t(permission.label)}{#if sensitivePermission(permission.id)} <span class="status">{t('roles.sensitive-permission')}</span>{/if}</label>{/each}</div></fieldset>{/if}{#if p.role.isBuiltIn}<Notice kind="info" text={t('roles.built-in-read-only')}/>{:else}<button class="button is-primary">{t('common.save')}</button>{/if}</form></section>{/if}</Page>
{:else}<Page title={boot.page.split('/').slice(-1)[0]?.replace(/_/g,' ')??'TowerDNS'} error={p.error} success={p.success}><AdminPage page={boot.page} data={p} {csrf}/></Page>{/if}
